///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_openCoupnRt
 * @description open Coupn Rt 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_openCoupnRt = async function () {
    const sbmOptions = {
        id: "tx_fn_openCoupnRt",
        method: "post",
        action: "/strip/strip.do?method=searchStripObjList",
        ref: "dma_openCoupnRtReq",
        target: "dlt_bndApctTpCdList=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fn_save
 * @description save 서버 호출
 * @param {*} action 제출 주소(호출부가 as-is form.action 으로 정하던 분기별 URL · 생략 시 기본 주소)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_save = async function (action) {
    const sbmOptions = {
        id: "tx_fn_save",
        method: "post",
        action: action ?? "/strip/strip.do?method=saveStripNew",
        ref: "dma_saveReq",
        target: "dlt_bndApctTpCdList=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fn_searchBndList
 * @description search Bnd List 서버 호출
 * @param {*} action 제출 주소(호출부가 as-is form.action 으로 정하던 분기별 URL · 생략 시 기본 주소)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_searchBndList = async function (action) {
    const sbmOptions = {
        id: "tx_fn_searchBndList",
        method: "post",
        action: action ?? "/strip/strip.do?method=searchStripBndList",
        ref: "dma_searchBndListReq",
        target: "dlt_bndApctTpCdList=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name CheckReqInfo_Cellphone
 * @description 표준 API 조합으로 새로 작성한 검사 함수
 * @param {*} fm fm
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.CheckReqInfo_Cellphone = async function (fm) { try { const v = (fm && fm.getValue) ? fm.getValue() : (fm && fm.value != null ? fm.value : null); if (v == null || String(v) === '') { return true; } if (!$c.str.isMobilePhone(String(v))) { await $c.win.alert('휴대전화번호 형식을 확인해 주세요.'); return false; } return true; } catch (_e) { return true; } };

/**
 * @method
 * @name mpd_files_selectCallback
 * @description mpd files select Callback 처리
 * @param {*} data 데이터
 * @returns {void}
 * @hidden N
 */
scwin.mpd_files_selectCallback = function (data) { const d = $c.util.getComponent('dlt_files'); if (!d) { return; } const rows = []; for (let i = 0; i < (data || []).length; i++) { rows.push({ FILE_NM: data[i].name, FILE_SIZE: String(data[i].size), CHK: '' }); } if (rows.length) { d.insertJSON(d.getRowCount(), rows); } };

/**
 * @method
 * @name openCoupnRt
 * @description open Coupn Rt 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.openCoupnRt = async function () {
    const fm = (document.SendForm || { elements: [] });
    if ($c.str.getByteLength($c.util.getComponent('ipt_sprtParAmt').getValue()) === 0) {
        await $c.win.alert("분리신청액면금액 입력하십시오.");
        $c.util.getComponent("ipt_sprtParAmt").focus();
        return false;
    } else {
        if ($c.str.getByteLength($c.util.getComponent('cal_bndFstSprtDd').getValue()) === 0) {
            await $c.win.alert("분리효력발생일을 입력하십시오.");
            $c.util.getComponent("cal_bndFstSprtDd").focus();
            return false;
        } else {
            const width = 1000;
            const height = 800;
            const mtWidth = document.body.clientWidth;
            const mtHeight = document.body.clientHeight;
            const scX = 0;
            const scY = 0;
            const popX = scX + (mtWidth - width) / 2;
            const popY = scY + (mtHeight - height) / 2;
            let _previewWindow;
            // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — "
            _previewWindow = (function(){ throw { bizMessage: "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — " + "/strip/strip.do?method=searchStripObjList", unresolved: "nav:" + "/strip/strip.do?method=searchStripObjList" }; })();
            fm.action = '/strip/strip.do?method=searchStripObjList';

        }
    }
    return;
};

/**
 * @method
 * @name save
 * @description save 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.save = async function () {
    if (!await scwin.checkData()) {
        return;
    } else {
        if (!await $c.win.confirm("신청하시겠습니까?")) {
            return false;
        }
    }
    $c.util.getComponent("dma_openCoupnRtReq").set("apctTelNo", $c.util.getComponent('ipt_apctTelNo1').getValue()+ '-' + $c.util.getComponent('ipt_apctTelNo2').getValue()+ '-' + $c.util.getComponent('ipt_apctTelNo3').getValue());
    $c.util.getComponent("dma_openCoupnRtReq").set("apctFaxNo", $c.util.getComponent('ipt_apctFaxNo1').getValue()+ '-' + $c.util.getComponent('ipt_apctFaxNo2').getValue()+ '-' + $c.util.getComponent('ipt_apctFaxNo3').getValue());
    $c.util.getComponent("dma_openCoupnRtReq").set("encrypApctEmail", $c.util.getComponent('ipt_encrypApctEmail1').getValue()+ '@' + $c.util.getComponent('ipt_encrypApctEmail2').getValue());
    await scwin.tx_fn_save('/strip/strip.do?method=saveStripNew');
};

/**
 * @method
 * @name checkData
 * @description check Data 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkData = async function () {
    const fm = (document.SendForm || { elements: [] });
    if ($c.str.getByteLength($c.util.getComponent('cal_procsReqDd').getValue()) === 0) {
        await $c.win.alert("적용희망일을 입력하십시오.");
        $c.util.getComponent("cal_procsReqDd").focus();
        return false;
    } else {
        if (WebSquare.date.getCurrentServerDate("yyyyMMdd") >= $c.util.getComponent('cal_procsReqDd').getValue().replace("-", "").replace("-", "")) {
            await $c.win.alert("적용희망일은 익일 이후만 입력가능합니다.");
            $c.util.getComponent("cal_procsReqDd").focus();
            return;
        } else {
            if ($c.str.getByteLength($c.util.getComponent('ipt_sprtParAmt').getValue()) === 0) {
                await $c.win.alert("분리신청액면금액을 입력하십시오.");
                $c.util.getComponent("ipt_sprtParAmt").focus();
                return false;
            } else {
                if ($c.str.getByteLength($c.util.getComponent('cal_bndFstSprtDd').getValue()) === 0) {
                    await $c.win.alert("분리효력발생일을 입력하십시오.");
                    $c.util.getComponent("cal_bndFstSprtDd").focus();
                    return false;
                } else {
                    if (!!!(($c.util.getComponent('dlt_files')) && ($c.util.getComponent('dlt_files')).getRowCount && ($c.util.getComponent('dlt_files')).getRowCount() > 0)) {
                        return false;
                    } else {
                        if (!CheckReqInfo(fm)) {
                            return false;
                        } else {
                            if (!await scwin.CheckReqInfo_Cellphone(fm)) {
                                return false;
                            }
                        }
                    }
                }
            }
        }
    }
    const rows = jQuery("#tbl_coupnRt tr");
    const rowCnt = rows.length - 1;
    if (rowCnt <= 0) {
        await $c.win.alert("만기별표면이자율을 입력하십시오.");
        return false;
    }
    let returnYn = true;
    /* 수동 전환 필요: 행 순회(id 선택자 #tbl_coupnRt) — 본문 열 참조로 dataList 를 못 정함(표가 마크업으로 남았으면 DOM 순회 유효 · 열 id 접두 검문) */ $("#tbl_coupnRt > tr").each(async function(idx) {
            if ($c.str.getByteLength($(this).find("#dtl_std_cd").val()) === 0) {
                returnYn = false;
                await $c.win.alert("만기별표면이자율을 입력하십시오.");
                return false;
            }
    });
    const totFileSize = (Math.round(((($c.util.getComponent('dlt_files')) && ($c.util.getComponent('dlt_files')).getRowCount) ? Array.from({ length: ($c.util.getComponent('dlt_files')).getRowCount() }, function (x, i) { return Number(($c.util.getComponent('dlt_files')).getCellData(i, 'FILE_SIZE')) || 0; }).reduce(function (a, b) { return a + b; }, 0) : 0) / (1024 * 1024) * 100) / 100);
    if (totFileSize > 100) {
        await $c.win.alert("전체 첨부파일의 크기는 최대 100MB까지 허용됩니다.\n현재 크기 = " + totFileSize + "MB");
        return false;
    }
    return returnYn;
};

